<script setup>
import {onMounted,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {getMyRefund} from '../../api/refund'
const route=useRoute(),router=useRouter(),data=ref({}),loading=ref(false);onMounted(async()=>{loading.value=true;try{data.value=(await getMyRefund(route.params.id)).data}finally{loading.value=false}})
</script>
<template><el-card v-loading="loading"><template #header><el-page-header @back="router.push('/user/refunds')"><template #content>退票详情</template></el-page-header></template><el-descriptions v-if="data.refundId" :column="2" border><el-descriptions-item label="退款编号">{{data.refundNo}}</el-descriptions-item><el-descriptions-item label="状态"><StatusTag :value="data.refundStatus"/></el-descriptions-item><el-descriptions-item label="订单号">{{data.orderNo}}</el-descriptions-item><el-descriptions-item label="退款金额">{{$formatMoney(data.refundAmount)}}</el-descriptions-item><el-descriptions-item label="比赛">{{data.homeClubName}} vs {{data.awayClubName}}</el-descriptions-item><el-descriptions-item label="比赛时间">{{$formatDateTime(data.matchTime)}}</el-descriptions-item><el-descriptions-item label="申请时间">{{$formatDateTime(data.appliedAt)}}</el-descriptions-item><el-descriptions-item label="审核时间">{{$formatDateTime(data.auditedAt)}}</el-descriptions-item><el-descriptions-item label="申请原因" :span="2">{{data.reason}}</el-descriptions-item><el-descriptions-item label="审核意见" :span="2">{{data.auditReason||'—'}}</el-descriptions-item></el-descriptions><el-empty v-else-if="!loading" description="退票记录不存在或无权查看"/></el-card></template>
